# The saints of Wales, region by region. build.py turns this into saints.html (all of Wales:
# Dewi first, the llan explainer, the map of the llannau, the regions, every saint, the
# calendar) and one saints-<id>.html page per region.
# House rules (see EDITORIAL.md): proud voice, nothing negative, contested points in the
# tradition's own words ("Welsh tradition holds", "his Life tells"). Most saints' Lives were
# written centuries after them, so dates are estimates and marked "c." or "fl.".
# Every line has English and Welsh.
#
# A saint:  S("id", "English name", "Welsh name", "dates", feast, "note EN", "note CY", places, link=..., key=...)
#   feast   = (day, month) or None when the date is not certain enough to print
#   places  = names from LL below: the llannau and churches that carry the saint's name
# A place:  LL["Welsh name"] = (lat, lon, "English name or None", away)  away=True: outside Wales, not on the map


def S(id, en, cy, dates, feast, nEn, nCy, places=(), link=None, key=False, y=None):
    return dict(id=id, en=en, cy=cy, dates=dates, feast=feast, nEn=nEn, nCy=nCy, places=list(places), link=link, key=key, y=y)


P = lambda s: f"person-{s}.html"  # noqa: E731

